detectionRules.code:
alert http $EXTERNAL_NET any -> $HTTP_SERVERS $HTTP_PORTS (
    msg:"ET EXPLOIT [CVE-2026-111497 / Node2Shell] Malformed Brotli Stream Heap Corruption Attempt";
    flow:established,to_server;
    http.method; content:"POST";
    http.header; content:"Content-Encoding|3a 20|br"; nocase;
    http.request_body; content:"|1b|"; startswith;
    /* Detect out-of-bounds sliding window & anomalous negative distance meta-block */
    byte_test:2,>,0x7FFF,0,relative;
    threshold:type limit, track by_src, count 1, seconds 60;
    reference:cve,2026-111497;
    classtype:attempted-admin;
    sid:2026102901;
    rev:2;
    metadata:affected_product NodeJS_DotNet_PHP, attack_target Web_Server, severity Critical;
)
